import{_ as s}from"./chunks/T7W828Q.Bql4mbKR.js";import{_ as a,o as p,c as e,ag as l}from"./chunks/framework.DUTPmUpA.js";const i="/_assets/5321426cdb.ChL0WAGj.png",h=JSON.parse('{"title":"События и модификаторы способностей, управляемых данными","description":"","frontmatter":{"title":"События и модификаторы способностей, управляемых данными","author":"Noya","steamId":"76561198046984233","date":"10.12.2014"},"headers":[],"relativePath":"abilities/datadriven/datadriven-ability-events-modifiers.md","filePath":"abilities/datadriven/datadriven-ability-events-modifiers.md"}'),t={name:"abilities/datadriven/datadriven-ability-events-modifiers.md"};function r(u,n,o,c,b,q){return p(),e("div",null,[...n[0]||(n[0]=[l('<p>каторы способностей, управляемых данными</p><p>Руководство, которое пытается охватить все события способностей и модификаторов системы <em>ability_datadriven</em> с примерами.</p><p><img src="'+s+`" alt="img"></p><p>Это руководство среднего уровня, требующее некоторых знаний о наиболее распространенных ключах-значениях первого уровня. Если вы не уверены в значении любого из них, проверьте <a href="/abilities/ability-keyvalues">DataDriven Ability Breakdown</a>.</p><h2 id="введение" tabindex="-1">Введение <a class="header-anchor" href="#введение" aria-label="Permalink to &quot;Введение&quot;">​</a></h2><p>В системе, управляемой данными, событие — это нечто, что срабатывает, когда происходит определенное внутриигровое событие, например, завершение применения способности.</p><p>Они имеют вид On[<em>EventTriggerKeyword</em>], например <code>OnSpellStart</code> <code>OnCreated</code> и т. д.</p><p>Существует полный (по большей части) <a href="https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools/Scripting/Abilities_Data_Driven#Ability_Events_and_Actions" target="_blank" rel="noreferrer">list of Events in the Workshop Tools Wiki</a>, но я собираюсь объяснить каждый из них на примерах того, как и когда их использовать.</p><p>В процессе я также буду использовать различные <a href="https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools/Scripting/Abilities_Data_Driven#Actions" target="_blank" rel="noreferrer">Actions</a> внутри событий, некоторые из них говорят сами за себя, а некоторые требуют подробного объяснения того, как их использовать.</p><p>Существует два типа: <strong>События способностей</strong> и <strong>События-модификаторы</strong>.</p><p>События способностей происходят на «первом уровне» способности. События модификатора должны находиться внутри блока модификатора. Базовый скелет выглядит так:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ability_custom&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // AbilityBehavior and General values</span></span>
<span class="line"><span>    // AbilityValues block</span></span>
<span class="line"><span>    // precache block</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Ability Events</span></span>
<span class="line"><span>    &quot;OnSpellStart&quot;</span></span>
<span class="line"><span>    { [ACTIONS] }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;Modifiers&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;modifier_custom&quot;</span></span>
<span class="line"><span>          {</span></span>
<span class="line"><span>            // Modifier Events</span></span>
<span class="line"><span>            &quot;OnCreated&quot;</span></span>
<span class="line"><span>            { [ACTIONS] }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p>Когда событие срабатывает, все действия, определенные в его блоке, будут выполнены.</p><p>Чтобы проверить, действительно ли ваше событие происходит тогда, когда вы ожидаете, вы можете добавить в него следующий блок действий:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;RunScript&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;ScriptFile&quot; &quot;utilities.lua&quot;</span></span>
<span class="line"><span>    &quot;Function&quot; &quot;Test&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>\`</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>RunScript\` — одно из самых распространенных и мощных действий, которые вы будете использовать для создания сложных способностей. Чтобы это работало, вам необходимо иметь файл сценария, в данном случае <em>utilities.lua</em>, внутри папки vscripts.</p><p>Вызываемая функция может иметь следующее:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function Test( event )</span></span>
<span class="line"><span>    print(&quot;It works!&quot;)</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Это отобразит на консоли переданные значения (обычно огромную таблицу), если ваш триггер события обнаружен правильно.</p><p>Я постараюсь держаться подальше от RunScript как действия, чтобы не превращать это в стену текста Dota Lua API, которая будет рассмотрена в другом, более продвинутом руководстве.</p><hr><h2 id="события-способностеи" tabindex="-1">События способностей <a class="header-anchor" href="#события-способностеи" aria-label="Permalink to &quot;События способностей&quot;">​</a></h2><h3 id="при-запуске-заклинания" tabindex="-1">При запуске заклинания <a class="header-anchor" href="#при-запуске-заклинания" aria-label="Permalink to &quot;При запуске заклинания&quot;">​</a></h3><p>Это срабатывает после завершения <code>AbilityCastPoint</code>. Если у вашего заклинания его нет (по умолчанию 0), оно будет применено, как только юнит окажется в точке применения.</p><p>Это событие встречается у каждой способности, чье свойство «AbilityBehavior» отлично от <code>DOTA_ABILITY_BEHAVIOR_PASSIVE</code>.</p><p><em>Пример</em>: Когда заклинание завершает свое применение, оно наносит урон всем юнитам в радиусе 500 от выбранной точки.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ability_active&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // General</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;BaseClass&quot;             &quot;ability_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityBehavior&quot;       &quot;DOTA_ABILITY_BEHAVIOR_POINT | DOTA_ABILITY_BEHAVIOR_AOE&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitTargetTeam&quot; &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitTargetType&quot; &quot;DOTA_UNIT_TARGET_HERO | DOTA_UNIT_TARGET_BASIC&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitDamageType&quot; &quot;DAMAGE_TYPE_MAGICAL&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Stats</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilityCastRange&quot; &quot;700&quot;</span><span>   // This will  also show a circle when hovering over the spell</span></span>
<span class="line"><span>    &quot;AbilityCastPoint&quot; &quot;0.5&quot;</span><span>   // Cast animation time</span></span>
<span class="line"><span>    &quot;AbilityCooldown&quot;  &quot;7&quot;</span></span>
<span class="line"><span>    &quot;AbilityManaCost&quot;  &quot;50 100 150 200&quot;</span></span>
<span class="line"><span>    &quot;AbilityDamage&quot;    &quot;100 200 300 400&quot;</span></span>
<span class="line"><span>    &quot;AOERadius&quot; &quot;500&quot;</span><span>  // This displays the AoE Helper, it doesn&#39;t have a real impact on the spell</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Special</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilitySpecial&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;01&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;var_type&quot; &quot;FIELD_INTEGER&quot;</span></span>
<span class="line"><span>            &quot;radius&quot; &quot;500&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Data Driven</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;OnSpellStart&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;Damage&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;Center&quot; &quot;POINT&quot;</span></span>
<span class="line"><span>                &quot;Radius&quot; &quot;%radius&quot;</span></span>
<span class="line"><span>                &quot;Teams&quot; &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>                &quot;Types&quot; &quot;DOTA_UNIT_TARGET_HERO | DOTA_UNIT_TARGET_BASIC&quot;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            &quot;Type&quot; &quot;DAMAGE_TYPE_MAGICAL&quot;</span></span>
<span class="line"><span>            &quot;Damage&quot; &quot;%AbilityDamage&quot;</span></span>
<span class="line"><span>         }</span></span>
<span class="line"><span>     }</span></span>
<span class="line"><span> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br></div></div><p><strong>Обратите внимание на использование <code>%radius</code> и других замен переменных, взятых из значенийabilitySpecial</strong>. Это настоятельно рекомендуется, так как это облегчит получение всплывающих подсказок и будущие изменения баланса.</p><p>Внутри действия по повреждению также есть блок <code>&quot;Target&quot;</code>. Это могла бы быть простая линия <code>&quot;Target&quot; &quot;TARGET&quot;</code> вместо блока с центральным радиусом и типами целей, если бы мы просто хотели, чтобы заклинание было нацелено на одну цель.</p><hr><h3 id="переключаемые-способности" tabindex="-1">Переключаемые способности <a class="header-anchor" href="#переключаемые-способности" aria-label="Permalink to &quot;Переключаемые способности&quot;">​</a></h3><h4 id="требуется-способностьbehavior-dota-ability-behavior-toggle" tabindex="-1">Требуется способностьBehavior: DOTA_ABILITY_BEHAVIOR_TOGGLE <a class="header-anchor" href="#требуется-способностьbehavior-dota-ability-behavior-toggle" aria-label="Permalink to &quot;Требуется способностьBehavior: DOTA_ABILITY_BEHAVIOR_TOGGLE&quot;">​</a></h4><ul><li>OnToggleOn</li><li>Вкл.ToggleВыкл.</li></ul><p><em>Пример</em>: включите ауру, которая усиливает ближайших союзников двойным уроном.</p><p>Для этого заклинания нам также необходимо использовать блок <code>precache</code>, который необходим для того, чтобы использованная вставка частицы отображалась в игре.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ability_toggle&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // General</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;BaseClass&quot;        &quot;ability_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityBehavior&quot;  &quot;DOTA_ABILITY_BEHAVIOR_NO_TARGET | DOTA_ABILITY_BEHAVIOR_TOGGLE&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Stats</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilityCastPoint&quot; &quot;0.5&quot;</span></span>
<span class="line"><span>    &quot;AbilityCooldown&quot;  &quot;0&quot;</span></span>
<span class="line"><span>    &quot;AbilityManaCost&quot;  &quot;20 30 40 50&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Special</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilitySpecial&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;01&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;var_type&quot; &quot;FIELD_INTEGER&quot;</span></span>
<span class="line"><span>            &quot;damage_bonus_percent&quot; &quot;100&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        &quot;02&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;var_type&quot; &quot;FIELD_INTEGER&quot;</span></span>
<span class="line"><span>            &quot;radius&quot; &quot;900&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;precache&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;particle&quot; &quot;particles/units/heroes/hero_medusa/medusa_mana_shield_snakeskin.vpcf&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Data Driven</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;OnToggleOn&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ApplyModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot;       &quot;CASTER&quot;</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_toggle&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    &quot;OnToggleOff&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;RemoveModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot;       &quot;CASTER&quot;</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_toggle&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;Modifiers&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;modifier_toggle&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Passive&quot;    &quot;0&quot;</span></span>
<span class="line"><span>            &quot;IsBuff&quot;     &quot;1&quot;</span></span>
<span class="line"><span>            &quot;IsPurgable&quot; &quot;0&quot;</span></span>
<span class="line"><span>            &quot;IsHidden&quot;   &quot;1&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            &quot;Aura&quot; &quot;toggle_aura&quot;</span></span>
<span class="line"><span>            &quot;Aura_Radius&quot; &quot;%radius&quot;</span></span>
<span class="line"><span>            &quot;Aura_Teams&quot; &quot;DOTA_UNIT_TARGET_TEAM_FRIENDLY&quot;</span></span>
<span class="line"><span>            &quot;Aura_Types&quot; &quot;DOTA_UNIT_TARGET_ALL&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        &quot;toggle_aura&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;IsBuff&quot; &quot;1&quot;</span></span>
<span class="line"><span>            &quot;IsHidden&quot; &quot;0&quot;</span></span>
<span class="line"><span>            &quot;Properties&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;MODIFIER_PROPERTY_BASEDAMAGEOUTGOING_PERCENTAGE&quot; &quot;%damage_bonus_percent&quot;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            &quot;EffectName&quot; &quot;particles/units/heroes/hero_medusa/medusa_mana_shield_snakeskin.vpcf&quot;</span></span>
<span class="line"><span>            &quot;EffectAttachType&quot; &quot;follow_origin&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br><span class="line-number">72</span><br><span class="line-number">73</span><br><span class="line-number">74</span><br><span class="line-number">75</span><br><span class="line-number">76</span><br><span class="line-number">77</span><br><span class="line-number">78</span><br><span class="line-number">79</span><br><span class="line-number">80</span><br></div></div><hr><h5 id="optional-cost-to-maintain" tabindex="-1"><em>Optional</em>: Cost to Maintain <a class="header-anchor" href="#optional-cost-to-maintain" aria-label="Permalink to &quot;_Optional_: Cost to Maintain&quot;">​</a></h5><p>For toggleable abilities, it&#39;s common to have a cost to maintain the ability. For this, we need to spend some mana at a time rate.</p><p>This requires the use of <code>OnIntervalThink</code> with a <code>RunScript</code> Action to spend the mana (which is done with Lua).</p><p><code>OnIntervalThink</code> is a Modifier Event (so it needs to be inside a modifier to work) used to repeat an effect every <code>ThinkInterval</code> seconds.</p><hr><h3 id="channeled-abilities" tabindex="-1">Channeled Abilities <a class="header-anchor" href="#channeled-abilities" aria-label="Permalink to &quot;Channeled Abilities&quot;">​</a></h3><h4 id="abilitybehavior-needed-dota-ability-behavior-channelled" tabindex="-1">AbilityBehavior Needed: DOTA_ABILITY_BEHAVIOR_CHANNELLED <a class="header-anchor" href="#abilitybehavior-needed-dota-ability-behavior-channelled" aria-label="Permalink to &quot;AbilityBehavior Needed: DOTA_ABILITY_BEHAVIOR_CHANNELLED&quot;">​</a></h4><p>There are 3 Events that control channels:</p><ul><li>OnChannelFinish</li><li>OnChannelInterrupted</li><li>OnChannelSucceeded</li></ul><p><code>OnChannelSucceeded</code> предназначен для завершенных каналов, <code>OnChannelInterrupted</code> для неисправных каналов, а <code>OnChannelFinish</code> срабатывает в любом случае. Как и в случае с любой способностью, вы можете добавить столько событий, сколько необходимо.</p><p><em>Пример</em>: Направленное поглощение HP. Эта способность также требует использования <code>OnIntervalThink</code> (событие-модификатор) для лечения и нанесения урона каждую секунду.</p><p><strong>Обратите внимание на <code>&quot;AbilityChannelTime&quot; &quot;10&quot;</code></strong>. Это ключевое значение также является обязательным для такого рода способностей.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ability_channel&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // General</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;BaseClass&quot; &quot;ability_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityBehavior&quot; &quot;DOTA_ABILITY_BEHAVIOR_UNIT_TARGET | DOTA_ABILITY_BEHAVIOR_CHANNELLED&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitTargetTeam&quot; &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitTargetType&quot; &quot;DOTA_UNIT_TARGET_HERO | DOTA_UNIT_TARGET_BASIC&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitDamageType&quot; &quot;DAMAGE_TYPE_MAGICAL&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Stats</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilityCastRange&quot; &quot;700&quot;</span></span>
<span class="line"><span>    &quot;AbilityCastPoint&quot; &quot;0.5&quot;</span></span>
<span class="line"><span>    &quot;AbilityCooldown&quot; &quot;3&quot;</span></span>
<span class="line"><span>    &quot;AbilityManaCost&quot; &quot;50&quot;</span></span>
<span class="line"><span>    &quot;AbilityDuration&quot; &quot;10&quot;</span></span>
<span class="line"><span>    &quot;AbilityChannelTime&quot; &quot;10&quot;</span><span>   // This sets the max time the spell can be channeled</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Special</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilitySpecial&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;01&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;var_type&quot; &quot;FIELD_INTEGER&quot;</span></span>
<span class="line"><span>            &quot;damage&quot; &quot;25&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Data Driven</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;OnSpellStart&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ApplyModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_drain&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    &quot;OnChannelFinish&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;RemoveModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_drain&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    &quot;OnChannelInterrupted&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;RemoveModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_drain&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;Modifiers&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;modifier_drain&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;IsDebuff&quot; &quot;1&quot;</span></span>
<span class="line"><span>            &quot;ThinkInterval&quot; &quot;1.0&quot;</span></span>
<span class="line"><span>            &quot;OnIntervalThink&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;Damage&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>                    &quot;Type&quot;   &quot;DAMAGE_TYPE_MAGICAL&quot;</span></span>
<span class="line"><span>                    &quot;Damage&quot; &quot;%damage&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>                &quot;Heal&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;HealAmount&quot; &quot;%damage&quot;</span></span>
<span class="line"><span>                    &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br><span class="line-number">72</span><br><span class="line-number">73</span><br><span class="line-number">74</span><br><span class="line-number">75</span><br><span class="line-number">76</span><br><span class="line-number">77</span><br><span class="line-number">78</span><br><span class="line-number">79</span><br><span class="line-number">80</span><br></div></div><hr><h3 id="owner-died-or-spawned" tabindex="-1">Owner died or spawned <a class="header-anchor" href="#owner-died-or-spawned" aria-label="Permalink to &quot;Owner died or spawned&quot;">​</a></h3><ul><li>OnOwnerDied</li><li>OnOwnerSpawned</li></ul><p><em>Example</em>: When the player with this spell dies, show an explosion and drop an item.</p><p>For the explosion, we need to use the CreateThinker action, which serves as a dummy to attach a particle effect (as trying to do so on the dead target usually won&#39;t work). Модификатор мыслителя player_death_fx имеет событие модификатора <code>OnCreated</code>, которое будет объяснено более подробно позже, но, как следует из названия, оно срабатывает, как только модификатор создан.</p><p>Удаление элемента выполняется с помощью действия <code>CreateItem</code>, которое имеет разные значения для управления свойствами создания.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ability_unit_died&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // General</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;BaseClass&quot; &quot;ability_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityBehavior&quot; &quot;DOTA_ABILITY_BEHAVIOR_PASSIVE&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;precache&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;particle&quot; &quot;particles/units/heroes/hero_lina/lina_spell_light_strike_array_explosion.vpcf&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Data Driven</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;OnOwnerDied&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        // Create a dummy at the dead units position to attach the particle effects</span></span>
<span class="line"><span>        &quot;CreateThinker&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;player_death_fx&quot;</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &quot;CreateItem&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            // This Target block is needed to be able to target dead units.</span></span>
<span class="line"><span>            &quot;Target&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;Center&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>                &quot;Flags&quot; &quot;DOTA_UNIT_TARGET_FLAG_DEAD&quot;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            &quot;ItemName&quot;       &quot;item_rapier&quot;</span></span>
<span class="line"><span>            &quot;ItemCount&quot;      &quot;1&quot;</span></span>
<span class="line"><span>            &quot;SpawnRadius&quot;    &quot;1&quot;</span></span>
<span class="line"><span>            &quot;LaunchHeight&quot;   &quot;300&quot;</span></span>
<span class="line"><span>            &quot;LaunchDistance&quot;    &quot;?1 100&quot;</span><span> // Min Max</span></span>
<span class="line"><span>            &quot;LaunchDuration&quot;    &quot;1.0&quot;</span></span>
<span class="line"><span>            // Optional</span></span>
<span class="line"><span>            //&quot;ItemChargeCount&quot; &quot;1&quot;</span><span> // This is used for charged consumable items</span></span>
<span class="line"><span>            //&quot;AutoUse&quot; &quot;1&quot;</span><span>         // If this is uncommented, item will be used when walking over</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;Modifiers&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;player_death_fx&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;OnCreated&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;AttachEffect&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;EffectName&quot; &quot;particles/units/heroes/hero_lina/lina_spell_light_strike_array_explosion.vpcf&quot;</span></span>
<span class="line"><span>                    &quot;EffectAttachType&quot; &quot;follow_origin&quot;</span></span>
<span class="line"><span>                    &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br></div></div><hr><h3 id="projectiles" tabindex="-1">Projectiles <a class="header-anchor" href="#projectiles" aria-label="Permalink to &quot;Projectiles&quot;">​</a></h3><h4 id="action-needed-trackingprojectile-or-linearprojectile" tabindex="-1">Action Needed: TrackingProjectile or LinearProjectile <a class="header-anchor" href="#action-needed-trackingprojectile-or-linearprojectile" aria-label="Permalink to &quot;Action Needed: TrackingProjectile or LinearProjectile&quot;">​</a></h4><ul><li>OnProjectileHitUnit</li><li>OnProjectileFinish</li></ul><p>These 2 Events provide detection for Projectile collision. <code>OnProjectileHitUnit</code> срабатывает при соединении с допустимым юнитом, а <code>OnProjectileFinish</code> срабатывает как при попадании в действующий юнит, так и при завершении его фиксированного расстояния.</p><p><strong>Примечание</strong>: <em>Необходимо полное руководство по двум различным действиям со снарядами. Это лишь краткое объяснение для поддержки базового примера</em>.</p><p>Есть два Действия, которые могут создавать снаряды. <code>LinearProjectile</code> нацелен на точку и будет следовать по прямой линии, а <code>TrackingProjectile</code> нацелен на объект и изменит свою траекторию, чтобы следовать за целью.</p><p>Ниже приведен пример значений для обоих действий.</p><h4 id="отслеживающии-снаряд" tabindex="-1">Отслеживающий снаряд <a class="header-anchor" href="#отслеживающии-снаряд" aria-label="Permalink to &quot;Отслеживающий снаряд&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;TrackingProjectile&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;Target&quot;           &quot;TARGET&quot;</span></span>
<span class="line"><span>    &quot;EffectName&quot;       &quot;particles/units/heroes/hero_enchantress/enchantress_impetus.vpcf&quot;</span></span>
<span class="line"><span>    &quot;Dodgeable&quot;        &quot;1&quot;</span></span>
<span class="line"><span>    &quot;ProvidesVision&quot;   &quot;1&quot;</span></span>
<span class="line"><span>    &quot;VisionRadius&quot;     &quot;300&quot;</span></span>
<span class="line"><span>    &quot;MoveSpeed&quot;        &quot;1000&quot;</span></span>
<span class="line"><span>    &quot;SourceAttachment&quot;  &quot;DOTA_PROJECTILE_ATTACHMENT_ATTACK_1&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h4 id="линеиныиснаряд" tabindex="-1">ЛинейныйСнаряд <a class="header-anchor" href="#линеиныиснаряд" aria-label="Permalink to &quot;ЛинейныйСнаряд&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;LinearProjectile&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;Target&quot;      &quot;POINT&quot;</span></span>
<span class="line"><span>    &quot;EffectName&quot;  &quot;particles/units/heroes/hero_mirana/mirana_spell_arrow.vpcf&quot;</span></span>
<span class="line"><span>    &quot;MoveSpeed&quot;   &quot;1100&quot;</span></span>
<span class="line"><span>    &quot;StartRadius&quot;   &quot;125&quot;</span></span>
<span class="line"><span>    &quot;StartPosition&quot; &quot;attach_attack1&quot;</span></span>
<span class="line"><span>    &quot;EndRadius&quot;     &quot;125&quot;</span></span>
<span class="line"><span>    &quot;FixedDistance&quot; &quot;1000&quot;</span></span>
<span class="line"><span>    &quot;TargetTeams&quot;   &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>    &quot;TargetTypes&quot;   &quot;DOTA_UNIT_TARGET_BASIC | DOTA_UNIT_TARGET_HERO&quot;</span></span>
<span class="line"><span>    &quot;TargetFlags&quot;   &quot;DOTA_UNIT_TARGET_FLAG_NONE&quot;</span></span>
<span class="line"><span>    &quot;HasFrontalCone&quot;    &quot;0&quot;</span></span>
<span class="line"><span>    &quot;ProvidesVision&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;VisionRadius&quot; &quot;300&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>Стоит отметить, что очень важно, чтобы система частиц <code>EffectName</code> имела необходимые свойства для каждого типа снаряда, а это означает, что если вы попытаетесь использовать частицу, предназначенную для отслеживания, в качестве LinearProjectile, это не сработает.</p><hr><p><em>Пример 1</em>: Линейный снаряд, который оглушает в радиусе, когда проходит фиксированное расстояние.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ability_projectile_linear&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // General</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;BaseClass&quot; &quot;ability_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityBehavior&quot; &quot;DOTA_ABILITY_BEHAVIOR_POINT&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitTargetTeam&quot; &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitTargetType&quot; &quot;DOTA_UNIT_TARGET_HERO | DOTA_UNIT_TARGET_BASIC&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitDamageType&quot; &quot;DAMAGE_TYPE_PURE&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Stats</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilityCastRange&quot; &quot;600&quot;</span></span>
<span class="line"><span>    &quot;AbilityDamage&quot; &quot;100&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Special</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilitySpecial&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;01&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;var_type&quot; &quot;FIELD_INTEGER&quot;</span></span>
<span class="line"><span>            &quot;distance&quot; &quot;600&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        &quot;02&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;var_type&quot; &quot;FIELD_INTEGER&quot;</span></span>
<span class="line"><span>            &quot;damage_aoe&quot; &quot;300&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;precache&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;particle&quot; &quot;particles/units/heroes/hero_mirana/mirana_spell_arrow.vpcf&quot;</span><span> //linear</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Data Driven</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;OnSpellStart&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;LinearProjectile&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;POINT&quot;</span></span>
<span class="line"><span>            &quot;EffectName&quot; &quot;particles/units/heroes/hero_mirana/mirana_spell_arrow.vpcf&quot;</span></span>
<span class="line"><span>            &quot;MoveSpeed&quot; &quot;600&quot;</span></span>
<span class="line"><span>            &quot;StartRadius&quot; &quot;125&quot;</span></span>
<span class="line"><span>            &quot;StartPosition&quot; &quot;attach_attack1&quot;</span></span>
<span class="line"><span>            &quot;EndRadius&quot; &quot;125&quot;</span></span>
<span class="line"><span>            &quot;FixedDistance&quot; &quot;500&quot;</span></span>
<span class="line"><span>            &quot;TargetTeams&quot; &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>            &quot;TargetTypes&quot; &quot;DOTA_UNIT_TARGET_BASIC | DOTA_UNIT_TARGET_HERO&quot;</span></span>
<span class="line"><span>            &quot;TargetFlags&quot; &quot;DOTA_UNIT_TARGET_FLAG_NONE&quot;</span></span>
<span class="line"><span>            &quot;HasFrontalCone&quot; &quot;0&quot;</span></span>
<span class="line"><span>            &quot;ProvidesVision&quot; &quot;1&quot;</span></span>
<span class="line"><span>            &quot;VisionRadius&quot; &quot;300&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnProjectileHitUnit&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;DeleteOnHit&quot; &quot;0&quot;</span><span> // This will make the projectile continues its trajectory after hitting</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnProjectileFinish&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ActOnTargets&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;Center&quot; &quot;POINT&quot;</span></span>
<span class="line"><span>                &quot;Radius&quot; &quot;%damage_aoe&quot;</span></span>
<span class="line"><span>                &quot;Teams&quot; &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>                &quot;Types&quot; &quot;DOTA_UNIT_TARGET_BASIC | DOTA_UNIT_TARGET_HERO&quot;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            &quot;Action&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;Stun&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;Duration&quot; &quot;1&quot;</span></span>
<span class="line"><span>                    &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br><span class="line-number">72</span><br><span class="line-number">73</span><br><span class="line-number">74</span><br><span class="line-number">75</span><br><span class="line-number">76</span><br><span class="line-number">77</span><br><span class="line-number">78</span><br><span class="line-number">79</span><br><span class="line-number">80</span><br><span class="line-number">81</span><br><span class="line-number">82</span><br><span class="line-number">83</span><br><span class="line-number">84</span><br><span class="line-number">85</span><br></div></div><hr><p><em>Example 2</em>: Spell without targeting that creates many TrackingProjectile-targeted enemies in radius, damaging them on hit.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ability_projectile_tracking&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // General</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;BaseClass&quot; &quot;ability_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityBehavior&quot; &quot;DOTA_ABILITY_BEHAVIOR_NO_TARGET&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitTargetTeam&quot; &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitTargetType&quot; &quot;DOTA_UNIT_TARGET_HERO | DOTA_UNIT_TARGET_BASIC&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitDamageType&quot; &quot;DAMAGE_TYPE_PURE&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Stats</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilityCastRange&quot; &quot;600&quot;</span></span>
<span class="line"><span>    &quot;AbilityDamage&quot; &quot;100&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Special</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilitySpecial&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;01&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;var_type&quot; &quot;FIELD_INTEGER&quot;</span></span>
<span class="line"><span>            &quot;radius&quot; &quot;1000&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;precache&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;particle&quot; &quot;particles/units/heroes/hero_enchantress/enchantress_impetus.vpcf&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Data Driven</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;OnSpellStart&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ActOnTargets&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;Center&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>                &quot;Radius&quot; &quot;%radius&quot;</span></span>
<span class="line"><span>                &quot;Teams&quot; &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>                &quot;Types&quot; &quot;DOTA_UNIT_TARGET_BASIC | DOTA_UNIT_TARGET_HERO&quot;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            &quot;Action&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;TrackingProjectile&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>                    &quot;EffectName&quot; &quot;particles/units/heroes/hero_enchantress/enchantress_impetus.vpcf&quot;</span></span>
<span class="line"><span>                    &quot;Dodgeable&quot; &quot;1&quot;</span></span>
<span class="line"><span>                    &quot;ProvidesVision&quot; &quot;1&quot;</span></span>
<span class="line"><span>                    &quot;VisionRadius&quot; &quot;300&quot;</span></span>
<span class="line"><span>                    &quot;MoveSpeed&quot; &quot;1000&quot;</span></span>
<span class="line"><span>                    &quot;SourceAttachment&quot; &quot;DOTA_PROJECTILE_ATTACHMENT_ATTACK_1&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnProjectileHitUnit&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;DeleteOnHit&quot; &quot;1&quot;</span></span>
<span class="line"><span>        &quot;Damage&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Type&quot; &quot;DAMAGE_TYPE_PHYSICAL&quot;</span></span>
<span class="line"><span>            &quot;Damage&quot; &quot;%AbilityDamage&quot;</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br></div></div><hr><p><strong>TODO:</strong> More on projectiles in a new tutorial</p><hr><h3 id="item-equip" tabindex="-1">Item Equip <a class="header-anchor" href="#item-equip" aria-label="Permalink to &quot;Item Equip&quot;">​</a></h3><p>These 2 Events are only to be used in <em>item_datadriven</em></p><ul><li>ОнЕкип</li><li>OnUnequip (не указан в вики)</li></ul><p>Важно помнить, что каждое Событие и Действие, которое работает для способности, также может быть использовано внутри <em>item_datadriven</em>. Предметы — это, по сути, способности, которые занимают разные слоты в пользовательском интерфейсе.</p><p><code>OnEquip</code> проверяется перед применением каких-либо модификаторов или бонусов, поэтому чрезвычайно полезно устанавливать ограничения на предметы (не разрешать герою носить определенный предмет, если соблюдено условие) и выполнять эффекты, как только предмет подбирается.</p><p><code>OnUnequip</code> — это самый прямой способ определить, когда предмет был выброшен (событие инвентаризации Lua нарушено). Это может быть полезно для удаления эффектов, добавленных с помощью сценариев, например добавления/улучшения способности.</p><p>Однако для этого потребуется некоторый тяжелый Lua, поэтому давайте упростим задачу и создадим событие для DataDriven Item, которое воспроизводит звук победы при выборе и звук поражения при падении.</p><p>Звуки мы пока не использовали, это обычный процесс:</p><h4 id="_1-получите-звуковую-струнную-линию" tabindex="-1">1. Получите звуковую струнную линию. <a class="header-anchor" href="#_1-получите-звуковую-струнную-линию" aria-label="Permalink to &quot;1. Получите звуковую струнную линию.&quot;">​</a></h4><p>Для этой цели я использую <a href="https://github.com/pingzing/dota2-sound-editor/releases" target="_blank" rel="noreferrer">Dota 2 Sound Editor</a> от pingzip.</p><p>В этом примере я хочу использовать звук Legion Commander Duel и немного жуткого звука Diretide, поэтому строки — <code>&quot;Hero_LegionCommander.Duel.Victory&quot;</code> и <code>&quot;diretide_roshdeath_Stinger&quot;</code>.</p><p><img src="`+i+`" alt="img"></p><p><strong>Выберите навык и нажмите Ctrl+C</strong></p><h4 id="_2-предварительно-кэшируите-звуковои-фаил" tabindex="-1">2. Предварительно кэшируйте звуковой файл. <a class="header-anchor" href="#_2-предварительно-кэшируите-звуковои-фаил" aria-label="Permalink to &quot;2. Предварительно кэшируйте звуковой файл.&quot;">​</a></h4><p>Чтобы найти его, зайдите в браузер ресурсов в инструментах и ​​введите <em>sounds</em> плюс часть героя/предмета/файла, в котором хранится звук. Поиск по «звукам легиона» и «звукам диретида» дает нам полные пути к звуковым файлам:</p><ul><li><code>&quot;soundevents/game_sounds_heroes/game_sounds_legion_commander.vsndevts&quot;</code></li><li><code>&quot;soundevents/game_sounds_stingers_diretide.vsndevts&quot;</code></li></ul><p><em>Пример</em>: Предмет со специальным звуком экипировки и выпадения. Многие значения предметов (например, стоимость или значок) опущены, чтобы сделать их короче, игра будет использовать множество значений по умолчанию.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;item_custom&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;ID&quot; &quot;1100&quot;</span></span>
<span class="line"><span>    &quot;BaseClass&quot; &quot;item_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityTexture&quot; &quot;item_rapier&quot;</span></span>
<span class="line"><span>    &quot;Model&quot; &quot;models/props_gameplay/recipe.vmdl&quot;</span></span>
<span class="line"><span>    &quot;Effect&quot; &quot;particles/generic_gameplay/dropped_item.vpcf&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;precache&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;soundfile&quot; &quot;soundevents/game_sounds_heroes/game_sounds_legion_commander.vsndevts&quot;</span></span>
<span class="line"><span>        &quot;soundfile&quot; &quot;soundevents/game_sounds_stingers_diretide.vsndevts&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnEquip&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;FireSound&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;EffectName&quot; &quot;Hero_LegionCommander.Duel.Victory&quot;</span></span>
<span class="line"><span>            &quot;Target&quot;     &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnUnequip&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;FireSound&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;EffectName&quot; &quot;diretide_roshdeath_Stinger&quot;</span></span>
<span class="line"><span>            &quot;Target&quot;     &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br></div></div><hr><p><strong>Tip</strong>: You can write <em>-item item_custom</em> with cheats enabled to give your main hero this item.</p><hr><p><strong>TODO:</strong> More on sounds in a new tutorial</p><hr><h3 id="другие-менее-распространенные-события-способностеи" tabindex="-1">Другие менее распространенные события способностей <a class="header-anchor" href="#другие-менее-распространенные-события-способностеи" aria-label="Permalink to &quot;Другие менее распространенные события способностей&quot;">​</a></h3><p>Никогда не пробовал это, нужно поэкспериментировать и дать несколько примеров ссылок. Некоторыми событиями также можно глобально управлять с помощью событий Lua, поэтому вы не увидите много кодов, использующих их.</p><h3 id="при-обновлении" tabindex="-1">При обновлении <a class="header-anchor" href="#при-обновлении" aria-label="Permalink to &quot;При обновлении&quot;">​</a></h3><p>Обновление способности из HUD. Полезно для способностей, содержащих несколько заклинаний, которые необходимо повышать вместе.</p><p><em>Пример</em>: уровень Spirit Bear повышается при обновлении заклинания, дополнительный мипо появляется при использовании ультимейта.</p><h3 id="onabilityphasestart" tabindex="-1">OnAbilityPhaseStart <a class="header-anchor" href="#onabilityphasestart" aria-label="Permalink to &quot;OnAbilityPhaseStart&quot;">​</a></h3><p>Срабатывает при применении способности (до того, как юнит повернется к цели). Фаза способности — это время между применением способности и моментом, когда отряду было приказано применить способность.</p><p><em>Пример</em>: Снайперский ульт</p><hr><h2 id="события-модификатора" tabindex="-1">События модификатора <a class="header-anchor" href="#события-модификатора" aria-label="Permalink to &quot;События модификатора&quot;">​</a></h2><h3 id="создавать-и-разрушать" tabindex="-1">Создавать и разрушать <a class="header-anchor" href="#создавать-и-разрушать" aria-label="Permalink to &quot;Создавать и разрушать&quot;">​</a></h3><ul><li>OnCreated — модификатор создан.</li><li>OnDestroy - модификатор удален. Чтобы применить или уничтожить модификатор (без значения <code>Passive</code>), есть два очень распространенных действия, которые обычно применяются событием способности, например <code>OnSpellStart</code>:</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ApplyModifier&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;ModifierName&quot; &quot;modifier_test&quot;</span></span>
<span class="line"><span>    &quot;Target&quot; TARGETKEY</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;RemoveModifier&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;ModifierName&quot; &quot;modifier_test&quot;</span></span>
<span class="line"><span>    &quot;Target&quot; TARGETKEY</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>При попытке <code>ApplyModifier</code> с <code>ModifierName</code>, который уже существует в цели, он переопределит его, если у него нет значения ключа <code>&quot;Attributes&quot; &quot;MODIFIER_ATTRIBUTE_MULTIPLE&quot;</code>.</p><p>Попытка использовать <code>RemoveModifier</code>, которого нет на устройстве, не вызовет никаких проблем.</p><p><em>Пример</em>: переключитесь, чтобы применить/удалить эффект частиц гниения на отряде с помощью этого заклинания.</p><p><code>AttachEffect</code> использует блок <code>ControlPoints</code> для управления радиусом системы частиц. В этом нет необходимости для большинства частиц, которые созданы как самоусиливающиеся, но поскольку в данном случае частица допускает переменный радиус, мы можем этим воспользоваться.</p><p><em>Каждая частица имеет свои собственные контрольные точки, и их обнаружение и управление ими — это тема для другого урока.</em></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ability_modifier_test&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // General</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;BaseClass&quot; &quot;ability_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityBehavior&quot; &quot;DOTA_ABILITY_BEHAVIOR_NO_TARGET | DOTA_ABILITY_BEHAVIOR_TOGGLE&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Stats</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilityManaCost&quot; &quot;0&quot;</span></span>
<span class="line"><span>    &quot;AbilityCooldown&quot; &quot;0&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Special</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilitySpecial&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;01&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;var_type&quot; &quot;FIELD_INTEGER&quot;</span></span>
<span class="line"><span>            &quot;radius&quot; &quot;500&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;precache&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;particle&quot; &quot;particles/units/heroes/hero_pudge/pudge_rot.vpcf&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Data Driven</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;OnToggleOn&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ApplyModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_example&quot;</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnToggleOff&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;RemoveModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_example&quot;</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;Modifiers&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;modifier_example&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;IsBuff&quot; &quot;1&quot;</span></span>
<span class="line"><span>            &quot;IsHidden&quot; &quot;0&quot;</span></span>
<span class="line"><span>            &quot;Passive&quot; &quot;0&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            // Modifier Events</span></span>
<span class="line"><span>            //-----------------------------------------------------------------------------</span></span>
<span class="line"><span>            &quot;OnCreated&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;AttachEffect&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>                    &quot;EffectName&quot; &quot;particles/units/heroes/hero_pudge/pudge_rot.vpcf&quot;</span></span>
<span class="line"><span>                    &quot;EffectAttachType&quot; &quot;follow_origin&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                    &quot;ControlPoints&quot;</span></span>
<span class="line"><span>                    {</span></span>
<span class="line"><span>                        &quot;00&quot; &quot;0 0 0&quot;</span></span>
<span class="line"><span>                        &quot;01&quot; &quot;%radius 0 0&quot;</span></span>
<span class="line"><span>                    }</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br><span class="line-number">72</span><br><span class="line-number">73</span><br><span class="line-number">74</span><br><span class="line-number">75</span><br><span class="line-number">76</span><br></div></div><hr><p>For the following examples I&#39;m gonna skip the AbilityBehavior, AbilitySpecials and other values and jump straight into the modifier blocks. You should be able to replace &quot;modifier_rot&quot; for a new modifier and change the Apply &amp; Remove, or just add new ones.</p><p>Every value with a % is a replacement of an AbilitySpecial, so make sure to also add those when adding new modifier examples.</p><hr><p><strong>TODO:</strong> More on Particle Attachments.</p><hr><h3 id="repeating-actions" tabindex="-1">Repeating actions <a class="header-anchor" href="#repeating-actions" aria-label="Permalink to &quot;Repeating actions&quot;">​</a></h3><ul><li>OnIntervalThink</li></ul><p>Together with <code>&quot;ThinkInterval&quot; &quot;%value&quot;</code> this will repeat the actions in this block every %value seconds.</p><p><em>Example</em>: Do damage per second for the duration of the modifier.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_dot&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;Duration&quot; &quot;%duration&quot;</span></span>
<span class="line"><span>    &quot;ThinkInterval&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;OnIntervalThink&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;Damage&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Type&quot; &quot;DAMAGE_TYPE_MAGICAL&quot;</span></span>
<span class="line"><span>            &quot;Damage&quot; &quot;%AbilityDamage&quot;</span></span>
<span class="line"><span>            &quot;Target&quot;    &quot;TARGET&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><hr><p><em>Example 2</em>: Expanding on the Toggle example, adding this to a modifier will call a Script Function every <code>ThinkInterval</code>. In this case, it calls a function to spend the mana and deactivate the ability when the cost per second can&#39;t be met.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    &quot;ThinkInterval&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;OnIntervalThink&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;RunScript&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;ScriptFile&quot; &quot;abilities.lua&quot;</span></span>
<span class="line"><span>            &quot;Function&quot;   &quot;maintain_toggle&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Скрипт очень прост:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function maintain_toggle( event )</span></span>
<span class="line"><span>    local manacost_per_second = 10</span></span>
<span class="line"><span>    -- if the caster has enough mana left to maintain the spell, spend it. Else, toggle the ability off</span></span>
<span class="line"><span>    if event.caster:GetMana() &gt;= manacost_per_second then</span></span>
<span class="line"><span>        event.caster:SpendMana( manacost_per_second, event.ability)</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        event.ability:ToggleAbility()</span></span>
<span class="line"><span>   end</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>Поместите его в файл сценария с именем <code>abilities.lua</code> внутри папки vscripts или измените путь к ScriptFile (он принимает относительные пути к vscripts).</p><hr><h3 id="атакующие-стартовые-и-приземляющиеся-атаки" tabindex="-1">Атакующие, стартовые и приземляющиеся атаки <a class="header-anchor" href="#атакующие-стартовые-и-приземляющиеся-атаки" aria-label="Permalink to &quot;Атакующие, стартовые и приземляющиеся атаки&quot;">​</a></h3><p>Существует 6 различных событий-модификаторов для обнаружения атак в разных точках:</p><ul><li>При атаке</li><li>При атаке</li><li>OnAttackStart</li><li>OnAttackLanded</li><li>Ошибка при атаке</li><li>OnAttackAllied</li></ul><hr><h3 id="при-атаке" tabindex="-1">При атаке <a class="header-anchor" href="#при-атаке" aria-label="Permalink to &quot;При атаке&quot;">​</a></h3><p>Юнит, к которому прикреплен этот модификатор, завершил атаку.</p><p><em>Пример</em>: экземпляр магического урона при каждой атаке. <em>Это сработает даже при промахах</em>. Для более управляемого триггера используйте события <code>OnAttackStart</code> и <code>OnAttackLanded</code>.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_magic_attack&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsBuff&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;Passive&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;0&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnAttack&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;Damage&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>           &quot;Type&quot; &quot;DAMAGE_TYPE_MAGICAL&quot;</span></span>
<span class="line"><span>           &quot;Damage&quot; &quot;%MagicDamage&quot;</span></span>
<span class="line"><span>           &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h3 id="onattacked" tabindex="-1">OnAttacked <a class="header-anchor" href="#onattacked" aria-label="Permalink to &quot;OnAttacked&quot;">​</a></h3><p>Юнит, к которому прикреплен этот модификатор, был атакован (срабатывает в конце атаки).</p><p><em>Пример</em>: Имитирует усиление «Вне боя» с 7-секундным «обнаружением боя».</p><p>Пассивно он обеспечивает усиление регенерации, но как в <code>OnAttack</code>, так и в <code>OnAttacked</code> применяется дебафф, добавляющий ту же регенерацию здоровья в качестве отрицательного значения. Поскольку модификатор уникален, если мы явно не сделаем его MULTIPLE, он будет применен только один раз.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_out_of_combat_buff&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsBuff&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;Passive&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;0&quot;</span></span>
<span class="line"><span>    &quot;Properties&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;MODIFIER_PROPERTY_HEALTH_REGEN_PERCENTAGE&quot; &quot;10&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Particle Effect to visualize it</span></span>
<span class="line"><span>    &quot;OnCreated&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;AttachEffect&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>            &quot;EffectName&quot; &quot;particles/units/heroes/hero_legion_commander/legion_commander_press.vpcf&quot;</span></span>
<span class="line"><span>            &quot;EffectAttachType&quot; &quot;follow_origin&quot;</span></span>
<span class="line"><span>            &quot;EffectLifeDurationScale&quot; &quot;1&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnAttacked&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ApplyModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_warchasers_solo_buff_combat&quot;</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    &quot;OnAttack&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ApplyModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_warchasers_solo_buff_combat&quot;</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;modifier_warchasers_solo_buff_combat&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;EffectName&quot; &quot;particles/items2_fx/satanic_buff.vpcf&quot;</span></span>
<span class="line"><span>    &quot;EffectAttachType&quot; &quot;follow_origin&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;Duration&quot; &quot;7&quot;</span></span>
<span class="line"><span>    &quot;Properties&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;MODIFIER_PROPERTY_HEALTH_REGEN_PERCENTAGE&quot; &quot;-10&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    &quot;Attributes&quot; &quot;MODIFIER_ATTRIBUTE_IGNORE_INVULNERABLE&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br></div></div><h3 id="onattackstart" tabindex="-1">OnAttackStart <a class="header-anchor" href="#onattackstart" aria-label="Permalink to &quot;OnAttackStart&quot;">​</a></h3><p>Юнит, к которому прикреплен этот модификатор, начал атаковать цель (когда начинается анимация атаки, а не когда создается снаряд автоатаки). Это можно использовать для применения модификаторов перед атакой, таких как крит.</p><p><em>Пример</em>: при начале атаки задайте случайный модификатор, который будет удален после ее окончания. Половина атак наносит критический урон, половина атак ненадолго оглушает заклинателя.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_luck&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;IsBuff&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;Passive&quot; &quot;1&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnAttackStart&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        // Remove the modifier on each attack start to disable people</span></span>
<span class="line"><span>        // from canceling attacks to get a guaranteed crit.</span></span>
<span class="line"><span>        &quot;RemoveModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_good_luck&quot;</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        &quot;Random&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Chance&quot; &quot;50&quot;</span></span>
<span class="line"><span>            &quot;OnSuccess&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;ApplyModifier&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;ModifierName&quot; &quot;modifier_good_luck&quot;</span></span>
<span class="line"><span>                    &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            &quot;OnFailure&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;Stun&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>                    &quot;Duration&quot; &quot;0.5&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;modifier_good_luck&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;Properties&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;MODIFIER_PROPERTY_PREATTACK_CRITICALSTRIKE&quot; &quot;%crit_bonus&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnAttackLanded&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;RemoveModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_good_luck&quot;</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br></div></div><h3 id="onattacklanded" tabindex="-1">OnAttackLanded <a class="header-anchor" href="#onattacklanded" aria-label="Permalink to &quot;OnAttackLanded&quot;">​</a></h3><p>Юнит, к которому прикреплен этот модификатор, атаковал цель.</p><p>Помимо использования его для удаления модификатора срабатывания атаки, как в последнем примере, мы можем использовать его для срабатывания эффектов только тогда, когда атака действительно попадает в цель (промахи не учитываются).</p><p><em>Пример</em>: Статический прирост здоровья и процент вампиризма.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_lifesteal&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;IsBuff&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;Passive&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;OnAttackLanded&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;Lifesteal&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;ATTACKER&quot;</span></span>
<span class="line"><span>            &quot;LifestealPercent&quot; &quot;%lifesteal&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        &quot;Heal&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;HealAmount&quot; &quot;20&quot;</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h3 id="onattackfailed" tabindex="-1">OnAttackFailed <a class="header-anchor" href="#onattackfailed" aria-label="Permalink to &quot;OnAttackFailed&quot;">​</a></h3><p>AttackFailed срабатывает при промахе. Вы можете использовать это, чтобы повторно применить модификатор, который не должен теряться при промахе, или сделать что-либо, связанное с эффектами после уклонения.</p><p><em>Пример</em>: после промаха дает дополнительную скорость атаки на некоторое время.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_on_miss&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;IsBuff&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;Passive&quot; &quot;1&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnAttackFailed&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ApplyModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;ModifierName&quot; &quot;modifier_extra_attackspeed&quot;</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;modifier_extra_attackspeed&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;Duration&quot; &quot;%duration&quot;</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;0&quot;</span></span>
<span class="line"><span>    &quot;IsBuff&quot;   &quot;1&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;Properties&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;MODIFIER_PROPERTY_ATTACKSPEED_BONUS_CONSTANT&quot;  &quot;%attack_speed_bonus&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><h3 id="onattackallied" tabindex="-1">OnAttackAllied <a class="header-anchor" href="#onattackallied" aria-label="Permalink to &quot;OnAttackAllied&quot;">​</a></h3><p>AttackAllied срабатывает при атаке юнитов одной команды. Это можно включить, добавив это к модификатору отряда, которого вы хотите атаковать:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  &quot;States&quot;</span></span>
<span class="line"><span>  {</span></span>
<span class="line"><span>      &quot;MODIFIER_STATE_SPECIALLY_DENIABLE&quot; &quot;MODIFIER_STATE_VALUE_ENABLED&quot;</span></span>
<span class="line"><span>  }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><em>Пример</em>: Отбрасывает союзников, атакуя их.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_knockback_attack&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;0&quot;</span></span>
<span class="line"><span>    &quot;IsBuff&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;Passive&quot; &quot;1&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnAttackAllied&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;Knockback&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>            &quot;Distance&quot; &quot;250&quot;</span></span>
<span class="line"><span>            &quot;Height&quot; &quot;75&quot;</span></span>
<span class="line"><span>            &quot;Duration&quot; &quot;0.5&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><hr><h2 id="damage-events" tabindex="-1">Damage Events <a class="header-anchor" href="#damage-events" aria-label="Permalink to &quot;Damage Events&quot;">​</a></h2><ul><li>OnDealDamage</li><li>OnTakeDamage</li></ul><hr><h3 id="ondealdamage" tabindex="-1">OnDealDamage <a class="header-anchor" href="#ondealdamage" aria-label="Permalink to &quot;OnDealDamage&quot;">​</a></h3><p>Юнит, к которому прикреплен этот модификатор, нанес урон.</p><p><em>Пример</em>: Вампиризм от всех источников урона.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_much_lifesteal&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsBuff&quot;    &quot;1&quot;</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;0&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnDealDamage&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;Lifesteal&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot;    &quot;ATTACKER&quot;</span></span>
<span class="line"><span>            &quot;LifestealPercent&quot;  &quot;%lifesteal&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h3 id="ontakedamage" tabindex="-1">OnTakeDamage <a class="header-anchor" href="#ontakedamage" aria-label="Permalink to &quot;OnTakeDamage&quot;">​</a></h3><p>Юнит, к которому прикреплен этот модификатор, получил урон. <code>%attack_damage</code> устанавливается на значение урона после смягчения.</p><p><em>Пример</em>: Возвратите весь полученный урон.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_return&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsBuff&quot;    &quot;1&quot;</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;0&quot;</span></span>
<span class="line"><span>    &quot;Duration&quot; &quot;%duration&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnTakeDamage&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;Damage&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot; &quot;ATTACKER&quot;</span></span>
<span class="line"><span>            &quot;Type&quot;   &quot;DAMAGE_TYPE_PHYSICAL&quot;</span></span>
<span class="line"><span>            &quot;Damage&quot; &quot;%attack_damage&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><hr><h2 id="killing-and-dying" tabindex="-1">Killing and Dying <a class="header-anchor" href="#killing-and-dying" aria-label="Permalink to &quot;Killing and Dying&quot;">​</a></h2><ul><li>OnDeath</li><li>OnKill</li><li>OnHeroKill</li><li>OnRespawn</li></ul><hr><h3 id="при-смерти" tabindex="-1">При смерти <a class="header-anchor" href="#при-смерти" aria-label="Permalink to &quot;При смерти&quot;">​</a></h3><p>Аналогично OnOwnerDied, но в качестве события-модификатора.</p><p>Имейте в виду, что действие <code>ApplyModifier</code> намного более управляемо и чисто, чем добавление способности к отряду, поэтому это ключ к заклинаниям типа «если отряд умрет с этим эффектом, он подойдет…».</p><p><em>Пример</em>: Когда юнит с этим модификатором умирает, он наносит урон в <em>радиусе</em>. Он имеет ограниченную <em>длительность</em>.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_damage_ondeath&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;0&quot;</span></span>
<span class="line"><span>    &quot;IsDebuff&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;Duration&quot; &quot;%duration&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnDeath&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;Damage&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Target&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;Center&quot; &quot;UNIT&quot;</span></span>
<span class="line"><span>                &quot;Radius&quot; &quot;%radius&quot;</span></span>
<span class="line"><span>                &quot;Teams&quot; &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>                &quot;Types&quot; &quot;DOTA_UNIT_TARGET_HERO | DOTA_UNIT_TARGET_BASIC&quot;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>            &quot;Type&quot;   &quot;DAMAGE_TYPE_MAGICAL&quot;</span></span>
<span class="line"><span>            &quot;Damage&quot; &quot;%AbilityDamage&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br></div></div><h3 id="при-убиистве" tabindex="-1">При убийстве <a class="header-anchor" href="#при-убиистве" aria-label="Permalink to &quot;При убийстве&quot;">​</a></h3><p>Это срабатывает, если юнит с модификатором убивает что-нибудь.</p><p><em>Пример</em>: Дайте бонусный_урон за каждого крипа, суммируясь.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;modifier_damage_onkill&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;Passive&quot; &quot;1&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;OnKill&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;ApplyModifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;ModifierName&quot;   &quot;modifier_damage_per_kill&quot;</span></span>
<span class="line"><span>            &quot;Target&quot;         &quot;CASTER&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;modifier_damage_per_kill&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;IsHidden&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;IsBuff&quot; &quot;1&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;Properties&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;MODIFIER_PROPERTY_PREATTACK_BONUS_DAMAGE&quot; &quot;%bonus_damage&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><p>В этом модификаторе индикатор усиления для каждого убийства скрыт, потому что в противном случае он бы отображал один значок усиления для каждого убитого юнита и быстро достигал бы предела. Значения <code>IsHidden</code> и <code>IsBuff</code> опущены в первом модификаторе, чтобы показать, что он будет использовать значения по умолчанию: <code>&quot;IsHidden&quot; &quot;0&quot;</code> и <code>&quot;IsBuff&quot; &quot;1&quot;</code>.</p><p>Для обработки стеков нам нужно использовать Lua.</p><h3 id="при-убиистве-героя" tabindex="-1">При убийстве героя <a class="header-anchor" href="#при-убиистве-героя" aria-label="Permalink to &quot;При убийстве героя&quot;">​</a></h3><p>В отличие от OnKill, это срабатывает только после убийства вражеского героя.</p><ul><li>Примеры: Урна, счетчики убийств Глушителем/Паджем, Кровавый камень.</li></ul><h3 id="при-возрождении" tabindex="-1">При возрождении <a class="header-anchor" href="#при-возрождении" aria-label="Permalink to &quot;При возрождении&quot;">​</a></h3><ul><li>Пример: возрождение нескольких персонажей при возрождении основного.</li></ul><hr><h2 id="эффекты-сфер" tabindex="-1">Эффекты сфер <a class="header-anchor" href="#эффекты-сфер" aria-label="Permalink to &quot;Эффекты сфер&quot;">​</a></h2><h4 id="требуется-способностьповедение-dota-ability-behavior-attack" tabindex="-1">Требуется способностьПоведение: DOTA_ABILITY_BEHAVIOR_ATTACK <a class="header-anchor" href="#требуется-способностьповедение-dota-ability-behavior-attack" aria-label="Permalink to &quot;Требуется способностьПоведение: DOTA_ABILITY_BEHAVIOR_ATTACK&quot;">​</a></h4><p>Эти три предназначены для совместного использования внутри модификатора:</p><ul><li>Сфера</li><li>ОнОрбФайр</li><li>ОнОрбИмпакт</li></ul><p>Сферы — это уникальные модификаторы атаки, которые не суммируются с другими сферами.</p><p>Наряду с атакующим поведением к этому типу способностей обычно добавляют <code>DOTA_ABILITY_BEHAVIOR_AUTOCAST</code>, <code>DOTA_ABILITY_BEHAVIOR_UNIT_TARGET</code> или <code>DOTA_ABILITY_BEHAVIOR_PASSIVE</code>.</p><p><em>Пример</em>: это автоматическое применение <code>Orb</code> со снарядом магической ракеты, который тратит ману как <code>OnOrbFire</code> и применяет модификатор, урон и звук <code>OnOrbImpact</code>. Modifier_black_arrow не учитывается — это может быть все, что мы уже видели.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;orb_example&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // General</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;BaseClass&quot; &quot;ability_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityBehavior&quot;   &quot;DOTA_ABILITY_BEHAVIOR_UNIT_TARGET | DOTA_ABILITY_BEHAVIOR_AUTOCAST | DOTA_ABILITY_BEHAVIOR_ATTACK&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitTargetTeam&quot; &quot;DOTA_UNIT_TARGET_TEAM_ENEMY&quot;</span></span>
<span class="line"><span>    &quot;AbilityUnitTargetType&quot; &quot;DOTA_UNIT_TARGET_HERO | DOTA_UNIT_TARGET_BASIC&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Stats</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilityCastRange&quot;  &quot;600&quot;</span></span>
<span class="line"><span>    &quot;AbilityManaCost&quot;   &quot;10&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;precache&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;particle&quot;  &quot;particles/units/heroes/hero_vengeful/vengeful_magic_missle.vpcf&quot;</span></span>
<span class="line"><span>        &quot;soundfile&quot; &quot;soundevents/game_sounds_heroes/game_sounds_medusa.vsndevts&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Special</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilitySpecial&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;01&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;var_type&quot;  &quot;FIELD_INTEGER&quot;</span></span>
<span class="line"><span>            &quot;bonus_damage&quot;  &quot;10 20 30 40&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Data Driven</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;Modifiers&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;modifier_orb&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Passive&quot;   &quot;1&quot;</span></span>
<span class="line"><span>            &quot;IsHidden&quot;  &quot;1&quot;</span></span>
<span class="line"><span>            &quot;Orb&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;Priority&quot;  &quot;DOTA_ORB_PRIORITY_ABILITY&quot;</span></span>
<span class="line"><span>                &quot;ProjectileName&quot; &quot;particles/units/heroes/hero_vengeful/vengeful_magic_missle.vpcf&quot;</span></span>
<span class="line"><span>                &quot;CastAttack&quot;    &quot;1&quot;</span><span> //This ensures the effect doesn&#39;t fire every time</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            &quot;OnOrbFire&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;SpendMana&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;Mana&quot; &quot;%AbilityManaCost&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            &quot;OnOrbImpact&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;ApplyModifier&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;ModifierName&quot;  &quot;modifier_black_arrow&quot;</span></span>
<span class="line"><span>                    &quot;Target&quot;    &quot;TARGET&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>               &quot;FireSound&quot;</span></span>
<span class="line"><span>               {</span></span>
<span class="line"><span>                   &quot;EffectName&quot; &quot;Hero_Medusa.MysticSnake.Target&quot;</span></span>
<span class="line"><span>                   &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>               }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>               &quot;Damage&quot;</span></span>
<span class="line"><span>               {</span></span>
<span class="line"><span>                   &quot;Type&quot; &quot;DAMAGE_TYPE_PHYSICAL&quot;</span></span>
<span class="line"><span>                   &quot;Damage&quot; &quot;%bonus_damage&quot;</span></span>
<span class="line"><span>                   &quot;Target&quot; &quot;TARGET&quot;</span></span>
<span class="line"><span>               }</span></span>
<span class="line"><span>          }</span></span>
<span class="line"><span>     }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br><span class="line-number">72</span><br><span class="line-number">73</span><br><span class="line-number">74</span><br><span class="line-number">75</span><br><span class="line-number">76</span><br><span class="line-number">77</span><br></div></div><hr><h2 id="other-less-common-modifier-events" tabindex="-1">Other less common Modifier Events <a class="header-anchor" href="#other-less-common-modifier-events" aria-label="Permalink to &quot;Other less common Modifier Events&quot;">​</a></h2><ul><li>Ability casting <ul><li>OnAbilityExecuted</li><li>OnAbilityEndChannel</li></ul></li><li>Health and Mana <ul><li>OnHealReceived</li><li>OnHealthGained</li><li>OnManaGained</li><li>OnSpentMana</li></ul></li><li>Движение <ul><li>На заказ</li><li>ОнUnitMoved</li><li>При телепортации</li><li>При телепортации</li></ul></li><li>Мисс Венеции <ul><li>OnProjectileDodge</li></ul></li><li>Другие <ul><li>OnStateChanged</li></ul></li></ul><h3 id="onabilityexecuted" tabindex="-1">OnAbilityExecuted <a class="header-anchor" href="#onabilityexecuted" aria-label="Permalink to &quot;OnAbilityExecuted&quot;">​</a></h3><p>Любая способность (включая предметы) использовалась отрядом с этим модификатором.</p><p><em>Пример</em>: Шанс обновления используемой способности. Блок <code>DelayedAction</code> предназначен для ожидания начала перезарядки навыка. Здесь используется простой сценарий Lua, поясняемый после кода способности, управляемой данными.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ability_preparation&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // General</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;BaseClass&quot; &quot;ability_datadriven&quot;</span></span>
<span class="line"><span>    &quot;AbilityBehavior&quot;   &quot;DOTA_ABILITY_BEHAVIOR_PASSIVE&quot;</span></span>
<span class="line"><span>    &quot;MaxLevel&quot; &quot;1&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &quot;precache&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;particle&quot;  &quot;particles/items2_fx/refresher.vpcf&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Special</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;AbilitySpecial&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;01&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;var_type&quot;  &quot;FIELD_INTEGER&quot;</span></span>
<span class="line"><span>            &quot;refresh_chance&quot;    &quot;5&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Data Driven</span></span>
<span class="line"><span>    //-------------------------------------------------------------------------------------</span></span>
<span class="line"><span>    &quot;Modifiers&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;preparation_modifier&quot;</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;Passive&quot;   &quot;1&quot;</span></span>
<span class="line"><span>            &quot;IsBuff&quot;    &quot;1&quot;</span></span>
<span class="line"><span>            &quot;IsHidden&quot;  &quot;1&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            &quot;OnAbilityExecuted&quot;</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;Random&quot;</span></span>
<span class="line"><span>                {</span></span>
<span class="line"><span>                    &quot;Chance&quot;    &quot;%refresh_chance&quot;</span></span>
<span class="line"><span>                    &quot;OnSuccess&quot;</span></span>
<span class="line"><span>                    {</span></span>
<span class="line"><span>                        &quot;DelayedAction&quot;</span></span>
<span class="line"><span>                        {</span></span>
<span class="line"><span>                            &quot;Delay&quot; &quot;0.1&quot;</span></span>
<span class="line"><span>                            &quot;Action&quot;</span></span>
<span class="line"><span>                            {</span></span>
<span class="line"><span>                                &quot;RunScript&quot;</span></span>
<span class="line"><span>                                {</span></span>
<span class="line"><span>                                    &quot;ScriptFile&quot;    &quot;abilities.lua&quot;</span></span>
<span class="line"><span>                                    &quot;Function&quot;  &quot;refresh_cooldowns&quot;</span></span>
<span class="line"><span>                                }</span></span>
<span class="line"><span>                            }</span></span>
<span class="line"><span>                        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                        &quot;FireSound&quot;</span></span>
<span class="line"><span>                        {</span></span>
<span class="line"><span>                            &quot;EffectName&quot;    &quot;DOTA_Item.Refresher.Activate&quot;</span></span>
<span class="line"><span>                            &quot;Target&quot; &quot;CASTER&quot;</span></span>
<span class="line"><span>                        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                        &quot;AttachEffect&quot;</span></span>
<span class="line"><span>                        {</span></span>
<span class="line"><span>                            &quot;EffectName&quot; &quot;particles/items2_fx/refresher.vpcf&quot;</span></span>
<span class="line"><span>                            &quot;EffectAttachType&quot; &quot;follow_origin&quot;</span></span>
<span class="line"><span>                        }</span></span>
<span class="line"><span>                    }</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br></div></div><p>Это очень простой Lua-скрипт. Она проходит через каждую способность, выполняя EndCooldown (проверять <code>ability:IsCooldownReady()</code> нам не нужно, функция в любом случае сработает).</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function refresh_cooldowns( event )</span></span>
<span class="line"><span>    print(&quot;refreshing cooldowns&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    local hero = event.caster</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    for i=0,4 do</span></span>
<span class="line"><span>        local ability = hero:GetAbilityByIndex(i)</span></span>
<span class="line"><span>        ability:EndCooldown()</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><hr><h3 id="onabilityendchannel" tabindex="-1">OnAbilityEndChannel <a class="header-anchor" href="#onabilityendchannel" aria-label="Permalink to &quot;OnAbilityEndChannel&quot;">​</a></h3><p>This triggers when the unit that has this modifier ends a channel (be it in any of the 3 types: <code>OnChannelFinish</code>, <code>Interrupted</code> or <code>Succeeded</code>).</p><hr><h3 id="onabilitystart-doesn-t-work" tabindex="-1">OnAbilityStart (doesn&#39;t work) <a class="header-anchor" href="#onabilitystart-doesn-t-work" aria-label="Permalink to &quot;OnAbilityStart (doesn&#39;t work)&quot;">​</a></h3><p>Отличие от OnSpellStart заключается в том, что это событие-модификатор, и вы можете применить его к цели, чтобы вызвать любые действия.</p><p><em>Пример</em>: примените модификатор, который убьет цель, как только она наложит заклинание, или заставит размер цели изменяться случайным образом каждый раз, когда она накладывает заклинание.</p><hr><h3 id="модификаторы-для-обнаружения-изменении-исцеления-и-маны-в-отряде" tabindex="-1">Модификаторы для обнаружения изменений исцеления и маны в отряде <a class="header-anchor" href="#модификаторы-для-обнаружения-изменении-исцеления-и-маны-в-отряде" aria-label="Permalink to &quot;Модификаторы для обнаружения изменений исцеления и маны в отряде&quot;">​</a></h3><h4 id="onhealreceived" tabindex="-1">OnHealReceived <a class="header-anchor" href="#onhealreceived" aria-label="Permalink to &quot;OnHealReceived&quot;">​</a></h4><p><em>Пример</em>: Oracle ult</p><h4 id="onhealthgained" tabindex="-1">OnHealthGained <a class="header-anchor" href="#onhealthgained" aria-label="Permalink to &quot;OnHealthGained&quot;">​</a></h4><p><em>Пример</em>: Wisp Tether</p><h4 id="onmanagained" tabindex="-1">OnManaGained <a class="header-anchor" href="#onmanagained" aria-label="Permalink to &quot;OnManaGained&quot;">​</a></h4><p><em>Пример</em>: Wisp Tether</p><h4 id="onspentmana" tabindex="-1">OnSpentMana <a class="header-anchor" href="#onspentmana" aria-label="Permalink to &quot;OnSpentMana&quot;">​</a></h4><h2 id="пример-оберег-пустоты" tabindex="-1"><em>Пример</em>: Оберег Пустоты <a class="header-anchor" href="#пример-оберег-пустоты" aria-label="Permalink to &quot;_Пример_: Оберег Пустоты&quot;">​</a></h2><h3 id="модификатор-событии-для-обнаружения-движения" tabindex="-1">Модификатор событий для обнаружения движения <a class="header-anchor" href="#модификатор-событии-для-обнаружения-движения" aria-label="Permalink to &quot;Модификатор событий для обнаружения движения&quot;">​</a></h3><h4 id="при-заказе" tabindex="-1">При заказе <a class="header-anchor" href="#при-заказе" aria-label="Permalink to &quot;При заказе&quot;">​</a></h4><p>Срабатывает при движении/применении/удержании/остановке</p><h4 id="onunitmoved" tabindex="-1">OnUnitMoved <a class="header-anchor" href="#onunitmoved" aria-label="Permalink to &quot;OnUnitMoved&quot;">​</a></h4><p><em>Пример</em>: ультимейт Bloodseeker</p><h4 id="при-телепортации" tabindex="-1">При телепортации <a class="header-anchor" href="#при-телепортации" aria-label="Permalink to &quot;При телепортации&quot;">​</a></h4><h4 id="при-телепортации-1" tabindex="-1">При телепортации <a class="header-anchor" href="#при-телепортации-1" aria-label="Permalink to &quot;При телепортации&quot;">​</a></h4><hr><h3 id="onprojectiledodge" tabindex="-1">OnProjectileDodge <a class="header-anchor" href="#onprojectiledodge" aria-label="Permalink to &quot;OnProjectileDodge&quot;">​</a></h3><p>Юнит с этим модификатором увернулся от снаряда.</p><hr><h3 id="онстатечанжед" tabindex="-1">Онстатечанжед <a class="header-anchor" href="#онстатечанжед" aria-label="Permalink to &quot;Онстатечанжед&quot;">​</a></h3><p>(Может) Срабатывает, когда юнит получает модификатор.</p>`,250)])])}const _=a(t,[["render",r]]);export{h as __pageData,_ as default};
